// ok[S]: S 是否为独立集
for (int S = 1; S < (1 << n); S++) {
	int v = __builtin_ctz(S), R = S ^ (1 << v);
	ok[S] = ok[R] && !(adj[v] & R);
}
// f[S]: 覆盖 S 最少几层；par[S]: 最优转移（最后一层 T）
vector<int> f(1 << n, n + 1), par(1 << n, -1);
f[0] = 0;
for (int S = 1; S < (1 << n); S++)
	for (int T = S; T; T = (T - 1) & S)          // 枚举 S 的所有非空子集
		if (ok[T] && f[S ^ T] + 1 < f[S]) f[S] = f[S ^ T] + 1, par[S] = T;
// 色数 = f[(1 << n) - 1]
// 方案：S = 全集; while (S) { T = par[S]; T 内所有点染当前颜色; S ^= T; }

int n, adj[30], color[30], bestK;
void dfs(int v, int k) {          // 已染前 v 个点，当前用了 k 种颜色
	if (k >= bestK) return;                       // 已经不比已知答案优
	if (v == n) { bestK = k; return; }            // 染完，刷新最优
	for (int c = 1; c <= min(k + 1, bestK - 1); c++) {
		bool ok = true;
		for (int u = 0; u < v; u++)
			if ((adj[v] >> u & 1) && color[u] == c) { ok = false; break; }
		if (!ok) continue;
		if (c == k + 1) {           // 新颜色与其它已有颜色完全对称，只需试一次
			color[v] = c; dfs(v + 1, k + 1); color[v] = 0; break;
		}
		color[v] = c; dfs(v + 1, k); color[v] = 0;
	}
}
